function HouseInfoMgr:OnTimer()
    local CurTime = nil  
    local QueryCallbackInfo = self.QueryCallbackInfo
    -- QuertData = {HouseID = HouseID, Callback = Callback, Time = NowTime}
    if next(QueryCallbackInfo) then
        CurTime = TimeUtil.GetServerTime()
        local QueryTime = 0
        for i = #QueryCallbackInfo, 1, -1 do
            QueryTime = QueryTime + 1
            local Info = QueryCallbackInfo[i]
            local HouseID = Info.HouseID
            local Basic = self.CacheHouseDetailInfo[HouseID] and self.CacheHouseDetailInfo[HouseID].Basic or {}
            local Roommates = self.CacheHouseDetailInfo[HouseID] and self.CacheHouseDetailInfo[HouseID].Roommates or {}
            if self.QueryTimeInfo[HouseID] and CurTime - self.QueryTimeInfo[HouseID] <= Queryinterval and self.CacheHouseDetailInfo[HouseID] then --避免2s内重复查询
                if Info.Callback then
                    Info.Callback(Basic, Roommates)
                end

                table.remove(self.QueryCallbackInfo, i)
            else
                if Info.Time and CurTime - Info.Time > QueryTimeOut then      --- 3s内重复查询都没回包 超时处理
                    if Info.Callback and self.CacheHouseDetailInfo[HouseID] then
                        Info.Callback(Basic, Roommates)
                    end

                    table.remove(self.QueryCallbackInfo, i)
                    FLOG_ERROR("HouseInfoMgr Query Detail TimeOut HouseID Is %s", HouseID)
                else
                    self.QueryCallbackInfo[i].Time = CurTime
                    self:SendHouseDetailInfo(HouseID)
                    break
                end
            end

            if QueryTime >= 5 then
                break
            end
        end
    end
end

