--获取个人房屋信息
function HouseInfoMgr:SendHouseRoleInfo()

    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PULL_ROLE_INFO
    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PullRoleInfo = {}
    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody, 0 , MajorUtil:GetMajorRoleID())
end

function HouseInfoMgr:RspHouseRoleInfo(MsgBody)
    if MsgBody and MsgBody.PullRoleInfo then
        if self.IsInit then
            self.MajorRoleID = MajorUtil:GetMajorRoleID()
            self.IsInit = false
        end
        self.SharedHouseID = MsgBody.PullRoleInfo.SharedHouseID
        self.MajorHouseID = MsgBody.PullRoleInfo.HouseID
        self:FreshCanVisitPanel()
        if MsgBody.PullRoleInfo.PersonalHouse then
            self.Roommates = MsgBody.PullRoleInfo.PersonalHouse.Roommates
            _G.EventMgr:SendEvent(EventID.HouseRoleInfoUpdate, MsgBody.PullRoleInfo.PersonalHouse)
        end


        if self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_Personal] then
            self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_Personal] = nil
        end

        if self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_GroupMemberRoom] then
            self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_GroupMemberRoom] = nil
        end

        local PersonalRecycleData = MsgBody.PullRoleInfo.PersonalRecycle
        if PersonalRecycleData and next(PersonalRecycleData.RecycleItemList) then
            self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_Personal] = PersonalRecycleData
        end

        local GroupRoomRecycleData = MsgBody.PullRoleInfo.GroupMemberRoomRecycle
        if GroupRoomRecycleData and next(GroupRoomRecycleData.RecycleItemList) then
            self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_GroupMemberRoom] = GroupRoomRecycleData
        end

        self.MajorHouseInfo = MsgBody.PullRoleInfo
        _G.EventMgr:SendEvent(EventID.PullSelfRoleHouseInfo)
        self:UpdatePersonalRecycleRed()
        self:UpdateSelfRoomRecycleRed()
    end
end

--获取房屋信息
function HouseInfoMgr:SendHouseDetailInfo(HouseID)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PULL_HOUSE_DETAIL
    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PullHouseDetail = {
        HouseID = HouseID
    }
    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody, 0, HouseID)
end

function HouseInfoMgr:RspHouseDetailInfo(MsgBody)
    if MsgBody and MsgBody.PullHouseDetail and MsgBody.PullHouseDetail.Detail then
        local Basic = MsgBody.PullHouseDetail.Detail.Basic
        local Roommates = MsgBody.PullHouseDetail.Detail.Roommates
        self.CacheHouseDetailInfo[Basic.HouseID] = {Basic = Basic, Roommates = Roommates}
        _G.EventMgr:SendEvent(EventID.HouseDetailInfoUpdate, MsgBody.PullHouseDetail.Detail)
        self:ProcessQueryCallback(Basic.HouseID)
        local NowTime = TimeUtil.GetServerTime()
        self.QueryTimeInfo[Basic.HouseID] = NowTime
    else
        if MsgBody and MsgBody.PullHouseDetail and MsgBody.PullHouseDetail.HouseID then
            local ErrorHouseID = MsgBody.PullHouseDetail.HouseID
            for i = #self.QueryCallbackInfo, 1, -1 do
                local Info = self.QueryCallbackInfo[i]
                local HouseID = Info.HouseID
                if HouseID == ErrorHouseID then
                    table.remove(self.QueryCallbackInfo, i)
                    FLOG_ERROR("InVaild House ID is : %s", ErrorHouseID)
                end
            end
        end
    end
end

--获取部队房屋信息
function HouseInfoMgr:SendGroupHouseInfo(GroupID)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PULL_GROUP_INFO
    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PullGroupInfo = {
        GroupID = GroupID
    }
    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody, 0, GroupID)
end

function HouseInfoMgr:RspGroupHouseInfo(MsgBody)
    self.ArmyHouseID = 0
    self.MajorArmyHouseInfo = {}
    if MsgBody and MsgBody.PullGroupInfo and MsgBody.PullGroupInfo.HouseDetail and MsgBody.PullGroupInfo.HouseDetail.Basic then
        local HouseID = MsgBody.PullGroupInfo.HouseDetail.Basic.HouseID
        if MsgBody.PullGroupInfo.GroupID == _G.ArmyMgr:GetArmyID() then
            self.ArmyHouseID = HouseID
            self.MajorArmyHouseInfo = MsgBody.PullGroupInfo

            _G.HousingMgr:SetArmyHouseID(HouseID)
            _G.HousingMgr:RefreshHouseID()
            _G.HousingMgr:SendHouseDepotReq(HouseID, ProtoRes.HouseRegionType.HouseRegionType_Room)
            _G.HousingMgr:SendHouseDepotReq(HouseID, ProtoRes.HouseRegionType.HouseRegionType_Yard)
            _G.HousingMgr:SendPullDecorateReq({HouseID}, ProtoRes.HouseRegionType.HouseRegionType_Room)
            _G.HousingMgr:SendPullDecorateReq({HouseID}, ProtoRes.HouseRegionType.HouseRegionType_Yard)
        end
    end

    if self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_Group] then
        self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_Group] = nil
    end

    if MsgBody and MsgBody.PullGroupInfo and MsgBody.PullGroupInfo.GroupRecycle then
        local GroupRecycleData = MsgBody.PullGroupInfo.GroupRecycle
        if GroupRecycleData and next(GroupRecycleData.RecycleItemList)then
            self.CacheRecycleAssets[AssestType.RecycleHouseAssetType_Group] = GroupRecycleData
        end
    end

    _G.EventMgr:SendEvent(EventID.HouseGroupInfoUpdate,MsgBody.PullGroupInfo)
    self:UpdateArmyRecycleRed()
    self:UpdateArmySelectionRed()
end

