function HouseInfoMgr:SendDoLikeReq(HouseID, IsLike)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_DO_LINKE
    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.DoLike = {
        HouseID = HouseID,
        IsLike = IsLike
    }
    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody, 0, self.MajorRoleID)
end

-- uint64  HouseID     = 1;    // 房屋ID
-- bool    IsLike      = 2;    // true: 点赞，false: 取消点赞
function HouseInfoMgr:RspDoLike(MsgBody)
    if next(self.MajorHouseInfo) and MsgBody.DoLike then
        local DolikeData = self.MajorHouseInfo.DoLikeInfo or {}
        local DolikeHouseData = DolikeData.DoLikedHouses or {}
        if not MsgBody.DoLike.IsLike then
            for i = #DolikeHouseData, 1, -1 do
                if MsgBody.DoLike.HouseID == DolikeHouseData[i] then
                    table.remove(DolikeHouseData, i)
                end
            end

        else
            table.insert(DolikeHouseData, MsgBody.DoLike.HouseID)
        end

        _G.EventMgr:SendEvent(EventID.DoLikeRsp, MsgBody.DoLike)
    end
end


