-- uint64                      HouseID     = 1;    // 房屋ID
-- repeated VisitPrivilegeOne  Setting     = 2; //  改变的设置
function HouseInfoMgr:RspSetPrivilegeBc(MsgBody)
    local Data = MsgBody and MsgBody.SetVisitPrivilegeBc or {}
    if not next(Data) then return end
    if self.CacheHouseDetailInfo[Data.HouseID] then
        local Basic = self.CacheHouseDetailInfo[Data.HouseID].Basic
        local CacheSetting = Basic.VisitSetting
        for k, v in pairs(Data.Setting) do
            for kk, vv in pairs(CacheSetting) do
                if vv.Type == v.Type then
                    Basic.VisitSetting[kk].Value = v.Value
                    break
                end
            end
        end
    end

    _G.EventMgr:SendEvent(EventID.HousePrivilegeChangeNotify, Data.HouseID)
end

