function HouseInfoMgr:RspCreateMemberRoom(MsgBody)
    if MsgBody and MsgBody.CreateGroupMemberRoom and next(MsgBody.CreateGroupMemberRoom) then
        MsgTipsUtil.ShowTips(HouseLocalDef.HouseArmyRoom.CreateRoomSuc)
        local Detail = MsgBody.CreateGroupMemberRoom.RoomDetail
        local Basic = Detail.Basic
        self.MajorMemberHouseID = Basic.HouseID

        self:SendPullMajorMemberRoom(_G.ArmyMgr:GetArmyID())
        self:SendPullArmyMemberRoom(_G.ArmyMgr:GetArmyID())
