end

function HouseInfoMgr:RspInviteReply(MsgBody)
    if MsgBody and MsgBody.InviteReply then
        local ReplyData = MsgBody.InviteReply
        local HouseID = ReplyData.HouseID
        if ReplyData.Reply then
            self.SharedHouseID = ReplyData.HouseID
            _G.HousingMgr:SetSharedHouseID(ReplyData.HouseID)
            _G.HousingMgr:RefreshHouseID()
        end

        self:QueryHouseDetail(HouseID, function(Basic, Roommates)
            local TipsIndex = ReplyData.Reply and 1 or 2
            local RoleVM = _G.RoleInfoMgr:FindRoleVM(Basic.OwnerID)
            MsgTipsUtil.ShowTips(string.format(HouseLocalDef.RoommatesInviteWinViewStr.InviteRspTips[TipsIndex], RoleVM.Name or ""))
            SidebarMgr:RemoveSidebarItemByParam(RoleVM.Name, "InviterName")
        end)

        _G.EventMgr:SendEvent(EventID.HouseInviteReplyRsp, ReplyData)
        self:SendGetInviteInformation()
    end
end

function HouseInfoMgr:NtfInviteReply(MsgBody)
    if MsgBody and MsgBody.InviteReplyNtf then
        local ReplyNtf = MsgBody.InviteReplyNtf
        local RoleVM = _G.RoleInfoMgr:FindRoleVM(ReplyNtf.RoleID)
        if ReplyNtf.Reply then
            self:SendHouseRoleInfo()
            MsgTipsUtil.ShowTips(string.format(HouseLocalDef.RoommatesInviteWinViewStr.InviteRspTips[3], RoleVM.Name))
            _G.EventMgr:SendEvent(EventID.HouseInviteReplyNtf, MsgBody.InviteReplyNtf)
        else
            MsgTipsUtil.ShowTips(string.format(HouseLocalDef.RoommatesInviteWinViewStr.InviteRspTips[4], RoleVM.Name))
        end
    end
end

