function HouseInfoMgr:GroupHouseDestroyNtf(MsgBody)
    if MsgBody and MsgBody.GroupHouseDestroyedToc then
        local HouseID = MsgBody.GroupHouseDestroyedToc.HouseID
        if HouseID == self.ArmyHouseID then
            local NeedUpdateRecycle = false
            local ArmyID = _G.ArmyMgr:GetArmyID()
            if ArmyID and ArmyID > 0 then
                if self.MajorMemberHouseID ~= 0 then
                    NeedUpdateRecycle = true
                    self.MajorMemberHouseID = 0
                    if next(self.MajorArmyHouseInfo) and self.MajorHouseInfo.HouseDetail and self.MajorHouseInfo.HouseDetail.Basic then 
                        self.MajorHouseInfo.HouseDetail.Basic.IsDestoried = true
                    end
                end

                self:RegisterTimer(function()
                    if NeedUpdateRecycle then
                        self:SendHouseRoleInfo()
                    end
                    self:SendGroupHouseInfo(ArmyID)
                end, 2, 0, 1)
            end
        end
    end
end
