--打开邀请侧边栏
function HouseInfoMgr:OpenHouseInviteSidebar(StartTime, CountDown, TransData, Type)

    local AcceptCallBack = function(_, Params)
        self:AcceptHouseInviteRequest(Params)
    end

    local RefuseCallBack = function(_, Params)
        self:RejectHouseInviteRequest(Params)
    end

    local Params = {
        Title       = HouseLocalDef.RoommateInviteSideBarTittle,
        Desc1       = string.format(HouseLocalDef.RoommateInviteSideBarContent, TransData.InviterName, TransData.HouseName), 
