        --透传数据
        TransData = TransData,
    }

    SidebarMgr:ShowCommonSidebarWin(Params)
end

--同意邀请
function HouseInfoMgr:AcceptHouseInviteRequest(TransData)
    if TransData.InvitorID == self.InvitorID then
        self:SendInviteReply(self.InvitorHouseID, true)
    end
    SidebarMgr:RemoveSidebarItemByParam(TransData.InviterName, "InviterName")
end

--拒绝邀请
function HouseInfoMgr:RejectHouseInviteRequest(TransData)
    if TransData.InvitorID == self.InvitorID then
        self:SendInviteReply(self.InvitorHouseID, false)
    end
    SidebarMgr:RemoveSidebarItemByParam(TransData.InviterName, "InviterName")
end

--侧边栏Item超时
function HouseInfoMgr:OnHouseInviteSidebarItemTimeOut(Type, TransData)
    if Type == HouseInviteSidebarType then
        SidebarMgr:RemoveSidebarItemByParam(TransData.InviterName, "InviterName")
    elseif Type == HouseLandAwardSidebarType then
        SidebarMgr:RemoveSidebarItemByParam(TransData.SelectionType, "SelectionType")
    end
end

