function HouseInfoMgr:OnExitArmy()
    self.ArmyHouseID = 0
    self.MajorArmyHouseInfo = {}
    self.MajorMemberHouseID = 0
    self:SendHouseRoleInfo()
end

function HouseInfoMgr:OnDestroyHouse(HouseID)
    if HouseID and HouseID ~= 0 then
        if HouseID == self.MajorHouseID then
            if next(self.MajorHouseInfo) and self.MajorHouseInfo.PersonalHouse and self.MajorHouseInfo.PersonalHouse.Basic then 
                self.MajorHouseInfo.PersonalHouse.Basic.IsDestoried = true
            end
            self:SendHouseRoleInfo()
        end
    end
end

function HouseInfoMgr:OnPWorldReady()
    self.VisitInDoorGroupID = 0
    local CurWorldSubType = _G.PWorldMgr:GetCurrPWorldSubType()
    if CurWorldSubType == ProtoRes.pworld_sub_type.PWORLD_SUB_TYPE_HOUSE_ROOM and _G.HousingMgr.IndoorHouseID > 0 then
        self:QueryHouseDetail(_G.HousingMgr.IndoorHouseID, function(Basic, Roommates)
            local HouseType = Basic.HouseType
            if HouseType == ProtoCS.HouseType.HouseType_HouseType_Group then
                self.VisitInDoorGroupID = Basic.OwnerID
            elseif HouseType == ProtoCS.HouseType.HouseType_HouseType_GroupMemberRoom then
                local RoleID = Basic.OwnerID
                _G.ArmyMgr:GetArmySimpleDataByRoleIDs({RoleID}, function(MsgBody)
                    if MsgBody and #MsgBody > 0 then
                        local Simple = MsgBody[1].Simple
                        self.VisitInDoorGroupID = Simple.ID
                    end
                end)
            else
                self.VisitInDoorGroupID = 0
            end
        end)
    end

    if self.CacheAutoPathData then
        _G.WorldMapMgr:StartMapAutoPathMove(self.CacheAutoPathData.MapID, self.CacheAutoPathData.Pos, self.CacheAutoPathData.Type, true)
        self.CacheAutoPathData = nil
    end

    ---- 延迟刷新全部红点
    self:RegisterTimer(function()
        self:UpdateAllRed()
    end, 3, 0, 1)
end
