--打开房屋信息界面
---@param PageNum number @ PageNum = 0 打开个人房屋信息 、PageNum = 2 打开部队房屋信息、 PageNum = 5 打开共享房屋信息
function HouseInfoMgr:OpenHouseInfoPanel(PageNum)
    local PageDefine = HouseLocalDef.MyHousePanelPageDefine
    self:FreshCanVisitPanel()
    if PageNum ~= PageDefine.PersonalHouse and PageNum ~= PageDefine.ArmyHouse and PageNum ~= PageDefine.ShareHouse then
        return
    end
    if self.HasMajorHouse == false and PageNum == PageDefine.PersonalHouse then
        return
    end
    if self.HasArmyHouse == false and PageNum == PageDefine.ArmyHouse then
        return
    end
    _G.HouseMineMainPanelVM.PageNum = PageNum
    _G.HouseMineMainPanelVM.SelectKey = 0
    UIViewMgr:ShowView(UIViewID.HouseMineMainPanelView)
end

-- 判断可以显示对应页签
function HouseInfoMgr:FreshCanVisitPanel()
    if self.MajorHouseID > 0 then
        self.HasMajorHouse = true
    else
        self.HasMajorHouse = false
    end

    if _G.ArmyMgr:CheckIsArmyUnlockLevel() ~= true or _G.ArmyMgr:GetArmyID() == 0 or _G.ArmyMgr:GetArmyLevel() < 9  or self.ArmyHouseID == 0 then  --目前部队只有8级 后续需要改成9级
        self.HasArmyHouse = false
    else
        self.HasArmyHouse = true
    end

    _G.HouseMineMainPanelVM:UpdateTabList()
end

