function HouseInfoMgr:GetHouseNameStr(RspHouseName, Addr, HouseType, RoomIndex)
    if RspHouseName == "" then
        if HouseType == ProtoCS.HouseType.HouseType_HouseType_GroupMemberRoom then
            local Str = HouseLocalDef.HouseInfoStr.ArmyRoomDefaultText
            return string.format(Str, RoomIndex or 0)
        else
            local Str = HouseLocalDef.HouseInfoStr.HouseDefaultText
            local EstateName = ""
            local EstateInfo = EstateInfoCfg:FindCfgByKey(Addr.EstateID)
            if EstateInfo then
                EstateName = EstateInfo.EstateName
            end

            return string.format(Str, EstateName, Addr.Area, Addr.Number)
        end
    else
        return RspHouseName
    end
end

---根据房屋ID查询房屋详细信息
---@param HouseID number
---@param Callback function
function HouseInfoMgr:QueryHouseDetail(HouseID, Callback)
    local NowTime = TimeUtil.GetServerTime()
    local IsUseCache = true
    if not self.QueryTimeInfo[HouseID] or not self.CacheHouseDetailInfo[HouseID] then
        IsUseCache = false
    else
        if NowTime - self.QueryTimeInfo[HouseID] > Queryinterval then   ---防止短时间重复查询 短时间重复查询用旧信息
            IsUseCache = false
        end
    end

    if IsUseCache then
        local Basic = self.CacheHouseDetailInfo[HouseID] and self.CacheHouseDetailInfo[HouseID].Basic or {}
        local Roommates = self.CacheHouseDetailInfo[HouseID] and self.CacheHouseDetailInfo[HouseID].Roommates or {}
        if Callback then
            Callback(Basic, Roommates)
        end
    else
        local QuertData = {HouseID = HouseID, Callback = Callback}
        table.insert(self.QueryCallbackInfo, QuertData)
    end
end

function HouseInfoMgr:ProcessQueryCallback(HouseID)
    local Basic = self.CacheHouseDetailInfo[HouseID] and self.CacheHouseDetailInfo[HouseID].Basic or {}
    local Roommates = self.CacheHouseDetailInfo[HouseID] and self.CacheHouseDetailInfo[HouseID].Roommates or {}
    for i = #self.QueryCallbackInfo, 1, -1 do
		local Info = self.QueryCallbackInfo[i]
        local HouseID = Info.HouseID
        if HouseID == Basic.HouseID then
            if Info.Callback then
                Info.Callback(Basic, Roommates)
            end

            table.remove(self.QueryCallbackInfo, i)
        end
	end
end

function HouseInfoMgr:GetHouseIconByHouseDetail(HouseDetailInfo)
    local Basic = HouseDetailInfo.Basic or {}
    local Roommates = HouseDetailInfo.Roommates or {}
    local CanVisited = _G.HouseLandMgr.GetVisitPrivile(Basic.OwnerID, Basic.VisitSetting, Roommates, ProtoCS.HouseVisitSettingType.HouseVisitSettingType_Enter, Basic.HouseType)
    local MajorID = MajorUtil.GetMajorRoleID()
    local IsMe = MajorID == Basic.OwnerID
    local IsRoommate = table.find_by_predicate(Roommates, function(Item)
        return Item.RoleID == MajorID
    end)

    local IsFriend = _G.FriendMgr:IsFriend(Basic.OwnerID)
    local IsArmyHouse = Basic.HouseType == ProtoCS.HouseType.HouseType_HouseType_Group
    local IsMyArmy = self.ArmyHouseID == Basic.HouseID
    local Index = 1

    if IsMe and not IsArmyHouse then
        Index = HouseLocalDef.HouseType.MyPersonalHouse
    end
    
    if IsMyArmy and IsArmyHouse then
        Index = HouseLocalDef.HouseType.MyArmyHouse
    end

    if CanVisited and not IsArmyHouse and not IsMe then
        Index = HouseLocalDef.HouseType.CanVisitPersonalHouse
    end

    if CanVisited and IsArmyHouse and not IsMyArmy then
        Index = HouseLocalDef.HouseType.CanVisitArmyHouse
    end

    if not CanVisited and not IsArmyHouse then
        Index = HouseLocalDef.HouseType.CanNotVisitPersonalHouse
    end

    if not CanVisited and IsArmyHouse then
        Index = HouseLocalDef.HouseType.CanNotVisitArmyHouse
    end

    if IsRoommate then
        Index = HouseLocalDef.HouseType.ShareHouse
    end

    local HouseDefInfo = HouseLocalDef.HouseTypeInfo[Index]
    local HouseCfg = require("TableCfg/HouseCfg")
    local HouseGetSizeInfo = HouseCfg:FindCfgByKey(Basic.HouseResID)
    local HouseSize = 1
    if HouseGetSizeInfo then
        HouseSize = HouseGetSizeInfo.Size + 1
    end

    return string.format(HouseLocalDef.LocationHouseIconPath, HouseLocalDef.LandSizeTypeStr[HouseSize], HouseDefInfo.IconIndex, HouseLocalDef.LandSizeTypeStr[HouseSize], HouseDefInfo.IconIndex)
end

function HouseInfoMgr:GetRealPosByPopRange(MapID, EtherPopRange)
    local MapEditCfg = _G.MapEditDataMgr:GetMapEditCfgByMapIDEx(MapID)
    local AreaList = MapEditCfg.AreaList
    for _, Area in ipairs(AreaList) do
        if Area.FuncType == ProtoRes.area_func_type.AREA_FUNC_TYPE_POP and EtherPopRange == Area.ID then
            local Position = nil
            if (Area.ShapeType == ProtoRes.area_shape_type.AREA_SHAPE_TYPE_BOX) then
                Position = _G.UE.FVector(Area.Box.Center.X, Area.Box.Center.Y, Area.Box.Center.Z)
            elseif (Area.ShapeType == ProtoRes.area_shape_type.AREA_SHAPE_TYPE_CYLINDER) then
                Position = _G.UE.FVector(Area.Cylinder.Start.X, Area.Cylinder.Start.Y, Area.Cylinder.Start.Z)
            end

            return Position
        end
    end
end

function HouseInfoMgr:TraceOrAutoMoveToHouse(AddrData)
    if not AddrData then
        FLOG_ERROR("TransToHouse Empty AddrData")
        return 
    end

    local LandCondCfg =  require("TableCfg/LandCondCfg")
    local LandSearchCondition = string.format("EstateID=%d and BlockID=%d ", AddrData.EstateID, AddrData.Number)
    local LandCfg = LandCondCfg:FindCfg(LandSearchCondition)
    local MapID = _G.HouseLandMgr:GetMapID(AddrData.EstateID or 1)
    local Pos = self:GetRealPosByPopRange(MapID, LandCfg.EtherPopRange)
    if not Pos then
        FLOG_ERROR("TransToHouse Empty Pos")
        return 
    end
    if _G.AutoPathMoveMgr:IsAutoPathMoveEnable() then
        local AutoMoveTargetType = require("Define/AutoMoveTargetType")
        local StreetID = _G.MapMgr:GetStreetID()
        if StreetID ~= AddrData.Area then
            _G.HouseLandMgr:SendLandTransmit(HouseLocalDef.LandTransmitType.Residence, AddrData)
            self.CacheAutoPathData = {
                MapID = MapID,
                Pos = Pos,
                Type = AutoMoveTargetType.Map,
            }
        else
            _G.WorldMapMgr:StartMapAutoPathMove(MapID, Pos, AutoMoveTargetType.Map, true)
        end
    else
        if _G.UIViewMgr:IsViewVisible(_G.UIViewID.WorldMapPanel) then
            _G.UIViewMgr:HideView(_G.UIViewID.WorldMapPanel)
        end

        local CurMapID = _G.PWorldMgr:GetCurrMapResID()
        local TargetMapID =  _G.HouseLandMgr:GetMapID(AddrData.EstateID or 1)
        local StreetID = _G.MapMgr:GetStreetID()
        local MapUtil = require("Game/Map/MapUtil")
        local UIMapID = MapUtil.GetUIMapID(CurMapID)
        if TargetMapID == CurMapID and AddrData.Area == StreetID then
            local MapDefine = require("Game/Map/MapDefine")
            local MarkerProviders = _G.MapMarkerMgr:GetMarkerProviders(MapDefine.MapMarkerType.HouseLand)
            if not MarkerProviders[1] or not MarkerProviders[1].MapMarkers then return end

            for i, Info in ipairs(MarkerProviders[1].MapMarkers) do
                local LandInfo = Info.LandInfo
                if LandInfo and LandInfo.ResidenceNumber == AddrData.EstateID and LandInfo.LandNumber == AddrData.Number  then
                    _G.WorldMapMgr:SetMapFollowInfo(AddrData.Number, MapDefine.MapMarkerType.HouseLand, 0, UIMapID, CurMapID, false, true)
                    break
                end
            end
        else
            _G.HouseLandMgr:ShowWorldMapHouseLand(AddrData.EstateID or 1, AddrData.Area or 1, AddrData.Number or 1)
            local WorldMapPanel = _G.UIViewMgr:FindView(_G.UIViewID.WorldMapPanel)
            local MarkerView, MapMaker = WorldMapPanel.MapContent:GetMapMarkerByLandAddr(AddrData.EstateID or 1,  AddrData.Number or 1)
            if MapMaker then
                MapMaker:ToggleFollow()
            end
        end
    end
end

---@param HouseID
---@param AddrData table  地址信息
---@param EtherGid number 私有水晶ID
---@param WorldID  number 房屋归属服务器ID 
function HouseInfoMgr:TransToHouse(HouseID, AddrData, EtherGid, WorldID)
    if _G.PWorldMgr:CurrIsInDungeon() then
        _G.MsgTipsUtil.ShowTips(HouseLocalDef.CantTransInPworld)
        return
    end

    if not HouseID then 
        FLOG_ERROR("HouseInfoMgr:TransToHouse Null HouseID")
        return
    end

    if EtherGid and EtherGid ~= 0 then
        local Params = {
            HouseID = HouseID,
            ClientTag = HouseLocalDef.LandTransmitClientTag.NoTips,
        }
        _G.HouseLandMgr:SendLandTransmit(HouseLocalDef.LandTransmitType.House, Params)
    else   
        local CurWorldID = _G.PWorldMgr:GetCurrWorldID()
        if WorldID and CurWorldID ~= WorldID then
            local Content = string.format(HouseLocalDef.OtherStr.CrossWorld, _G.LoginMgr:GetMapleNodeName(WorldID))
                CrossWorldUtil.CrossWorldWithoutCrtstal(WorldID, Content, "", nil, function()
                    self:TraceOrAutoMoveToHouse(AddrData)
                end)
        else
            self:TraceOrAutoMoveToHouse(AddrData)
        end
    end
end

function HouseInfoMgr:IsCurHouseHasLiked(HouseID)
    if next(self.MajorHouseInfo) then
        local DolikeData = self.MajorHouseInfo.DoLikeInfo or {}
        local DolikeHouseData = DolikeData.DoLikedHouses or {}
        for i, v in ipairs(DolikeHouseData) do
            if v == HouseID then
                return true
            end
        end
    end

    return false
end

function HouseInfoMgr:GetRecycleDataByRecycleType(Type)
    return self.CacheRecycleAssets[Type] and self.CacheRecycleAssets[Type] or {}
end

--- 是否有资产需要回收
function HouseInfoMgr:IsHouseAssetsNeedRecycle()
    local ShowRecycle = false
    local DeinfeData = HouseLocalDef.RecycleAssetsTab
	for i, v in ipairs(DeinfeData) do
		local RecyclyData = self:GetRecycleDataByRecycleType(v.Key)
		if next(RecyclyData) then
			ShowRecycle = true
            break
		end
	end

    return ShowRecycle
end
