function HouseInfoMgr:InitHouseRedDotFun()
	if self.HouseSysRedDotFun == nil then
		self.HouseSysRedDotFun = {}
	end

	self.HouseSysRedDotFun[RedDefine.MySelectionRedDot]   = {Fun = self.UpdateMySelectionRed}
	self.HouseSysRedDotFun[RedDefine.ArmySelectionRedDot] = {Fun = self.UpdateArmySelectionRed}
	self.HouseSysRedDotFun[RedDefine.PersonRecycle]       = {Fun = self.UpdatePersonalRecycleRed}
    self.HouseSysRedDotFun[RedDefine.ArmyRecycle]         = {Fun = self.UpdateArmyRecycleRed}
    self.HouseSysRedDotFun[RedDefine.SelfRoomRecycle]     = {Fun = self.UpdateSelfRoomRecycleRed}
    self.HouseSysRedDotFun[RedDefine.HouseFirstUnLock]    = {Fun = self.UpdateHouseSysFirstUnLock}
    self.HouseSysRedDotFun[RedDefine.ShareHouseInvite]    = {Fun = self.UpdateShareHouseInvite}
end

--- 玩家中选未建房 或者未中选未领取返还货币 展示红点
function HouseInfoMgr:UpdateMySelectionRed()
    local CurRedID  = RedDefine.MySelectionRedDot
    RedDotMgr:DelRedDotByID(CurRedID)
    local LandSelectInfo = _G.HouseLandMianPanelVM.LandSelectInfo
    if not LandSelectInfo  or not next(LandSelectInfo) then return end

    local OriginWorldID = _G.LoginMgr:GetWorldID()  -- 原始WorldID
    local WorldID = _G.PWorldMgr:GetCurrWorldID()
    local IsCrossWorld = OriginWorldID ~= WorldID 
    local NotBuild = _G.HouseLandMianPanelVM.CurBuyStateInfo.BuildStatus == ProtoCS.BuildStatusType.BuildStatus_CanBuild 
    if LandSelectInfo and LandSelectInfo[HouseLocalDef.BuyHouseBelongType.Personal] then
        local LatestApply = LandSelectInfo[HouseLocalDef.BuyHouseBelongType.Personal]
        if LatestApply.PhaseID == _G.HouseLandMianPanelVM.PhaseCnt and LatestApply.AplStatus == ProtoCS.ApplyStatus.ApplyStatus_Award and NotBuild and not IsCrossWorld then
            RedDotMgr:AddRedDotByID(CurRedID)
            FLOG_INFO("ZYH HouseInfoMgr:UpdateMySelectionRed 中选")
        elseif LatestApply.ReturnMoney > 0 and LatestApply.AplStatus ~= ProtoCS.ApplyStatus.ApplyStatus_Return then
            RedDotMgr:AddRedDotByID(CurRedID)
            FLOG_INFO("ZYH HouseInfoMgr:UpdateMySelectionRed 未领取返还货币")
        end
    end
end

--- 部队房屋中选未建房时，对所有拥有“购买土地和建造房屋”权限的玩家显示部队抽选红点
function HouseInfoMgr:UpdateArmySelectionRed()
    local CurRedID  = RedDefine.ArmySelectionRedDot
    RedDotMgr:DelRedDotByID(CurRedID)
    local OriginWorldID = _G.LoginMgr:GetWorldID()  -- 原始WorldID
    local WorldID = _G.PWorldMgr:GetCurrWorldID()
    local IsCrossWorld = OriginWorldID ~= WorldID 
    local IsPremission = _G.ArmyMgr:GetSelfIsHavePermisstion(ProtoRes.GroupPermissionType.PermissionTypeEstatePurchaseLandAndBuild)
    local LandSelectInfo = _G.HouseLandMianPanelVM.LandSelectInfo
    local NoBuild = _G.HouseLandMgr.GroupHasLandNoBuild()
    if LandSelectInfo and LandSelectInfo[HouseLocalDef.BuyHouseBelongType.Army] and IsPremission and NoBuild and not IsCrossWorld then
        local LatestApply = LandSelectInfo[HouseLocalDef.BuyHouseBelongType.Army]
        if LatestApply.PhaseID == _G.HouseLandMianPanelVM.PhaseCnt then
            RedDotMgr:AddRedDotByID(CurRedID)
            FLOG_INFO("ZYH HouseInfoMgr:UpdateArmySelectionRed")
        end
    end
end

--- 个人房屋被系统撤除时，对房主显示资产回收红点
function HouseInfoMgr:UpdatePersonalRecycleRed()
    local CurRedID  = RedDefine.PersonRecycle
    RedDotMgr:DelRedDotByID(CurRedID)
    local RecyclyData = self:GetRecycleDataByRecycleType(AssestType.RecycleHouseAssetType_Personal)
    if next(RecyclyData) then
        RedDotMgr:AddRedDotByID(CurRedID)
