--- 解锁房屋系统时，二级菜单房屋入口显示红点
function HouseInfoMgr:UpdateHouseSysFirstUnLock()
    local CurRedID  = RedDefine.HouseFirstUnLock
    if not ModuleOpenMgr:CheckOpenState(ProtoCommon.ModuleID.ModuleIDHOUSE) then return end
    RedDotMgr:DelRedDotByID(CurRedID)
    local JsonStr = USaveMgr.GetString(SaveKey.HouseSystem, "", true)
    local HouseRedData = string.isnilorempty(JsonStr) and {} or Json.decode(JsonStr)
    if not HouseRedData.HasSeen then
        RedDotMgr:AddRedDotByID(CurRedID)
        FLOG_INFO("ZYH HouseInfoMgr:UpdateHouseSysFirstUnLock")
    end
end

