function HouseInfoMgr:SaveFirstSeen()
    local JsonStr = USaveMgr.GetString(SaveKey.HouseSystem, "", true)
    local HouseRedData = string.isnilorempty(JsonStr) and {} or Json.decode(JsonStr)
    HouseRedData.HasSeen = 1
    local SaveJsonStr = Json.encode(HouseRedData)
    USaveMgr.SetString(SaveKey.HouseSystem, SaveJsonStr, true)

    self:UpdateHouseSysFirstUnLock()
end

--- 拆了房子 土地还在
function HouseInfoMgr:IsPersonalHouseDestroied()
    if not next(self.MajorHouseInfo) then return false end

    local Basic = self.MajorHouseInfo.PersonalHouse and self.MajorHouseInfo.PersonalHouse.Basic or {}
    return Basic.IsDestoried
end

--- 拆了房子 土地还在
function HouseInfoMgr:IsMajorArmyHouseDestroied()
    if not next(self.MajorArmyHouseInfo) then return false end

    local Basic = self.MajorArmyHouseInfo.HouseDetail and self.MajorArmyHouseInfo.HouseDetail.Basic or {}
    return Basic.IsDestoried
end

function HouseInfoMgr:IsCurHouseLandCanGiveUp(HouseID)
    if HouseID == self.MajorHouseID  then
        return self:IsPersonalHouseDestroied()
    elseif HouseID == self.ArmyHouseID then
        return  self:IsMajorArmyHouseDestroied()
    else
        return false
    end
end

