function HouseInfoMgr:LoginAfterGetDataAddSideBar()
    local OriginWorldID = _G.LoginMgr:GetWorldID()  -- 原始WorldID
    local WorldID = _G.PWorldMgr:GetCurrWorldID()
    local IsCrossWorld = OriginWorldID ~= WorldID 
    if _G.HouseLandMianPanelVM.LandSelectInfo and not self.HasPopAwardSideBar and not IsCrossWorld then
        local StartTime = TimeUtil.GetServerTime()
        local Duration = 30
        local TransData = {
            SelectionType = ProtoCS.HouseType.HouseType_HouseType_Personal
        }

        local GroupNoBuild, _, GroupIsDestroy = _G.HouseLandMgr.GroupHasLandNoBuild()
        local SelfNoBuild, _, SelfIsDestroy = _G.HouseLandMgr.SelfHasLandNoBuild()
        if GroupNoBuild and not GroupIsDestroy then
            TransData.SelectionType = ProtoCS.HouseType.HouseType_HouseType_Group
            SidebarMgr:AddSidebarItem(HouseLandAwardSidebarType, StartTime, Duration, TransData ,true)
            self.HasPopAwardSideBar = true
            _G.MsgTipsUtil.ShowInfoTextTips(3, HouseLocalDef.HouseInfoText, "", 1) --
        elseif SelfNoBuild and not SelfIsDestroy then
            SidebarMgr:AddSidebarItem(HouseLandAwardSidebarType, StartTime, Duration, TransData ,true)
            _G.MsgTipsUtil.ShowInfoTextTips(3, HouseLocalDef.HouseInfoText, "", 1) --
            self.HasPopAwardSideBar = true
        end
    end
end

