function HouseInfoMgr:OpenHouseSelectionAwardSidebar(StartTime, CountDown, TransData, Type)
    local AcceptCallBack = function(_, Params)
        _G.HouseLandMgr:OpenHouseOrLandPanel(_G.HouseLandMianPanelVM.LandSelectInfo[TransData.SelectionType])
        SidebarMgr:RemoveSidebarItemByParam(TransData.SelectionType, "SelectionType")
    end

    local RefuseCallBack = function(_, Params)
        SidebarMgr:RemoveSidebarItemByParam(TransData.SelectionType, "SelectionType")
    end

    local Params = {
        Title       = string.format(HouseLocalDef.HouseLandAwardTitle, HouseLocalDef.BuyHouseBelongTypeStr[TransData.SelectionType]),
        Desc1       = HouseLocalDef.HouseLandAwardContent, 
        StartTime   = StartTime,
        CountDown   = CountDown,
        CBFuncLeft  = RefuseCallBack,
        CBFuncRight = AcceptCallBack,
        Type        = Type,
        BtnTextLeft = HouseLocalDef.HouseLandAwardCancel,
        BtnTextRight = HouseLocalDef.HouseLandAwardConfirm,

        --透传数据
        TransData = TransData,
    }

    self.HasPopAwardSideBar = true
    SidebarMgr:ShowCommonSidebarWin(Params)
end

function HouseInfoMgr:GetHouseRoomatesPermission()
    local HousePermissionCfg = require("TableCfg/HousePermissionCfg")
    local AllCfg = HousePermissionCfg:FindAllCfg() or {}
    local Data = {}
	for i, v in ipairs(AllCfg) do
        local Item = {
            PrivilegeName = v.Name,
            Selected = false,
            Index = i,
            IsShow = v.IsShareShow == 1
        }

        table.insert(Data, Item)
    end

    return Data
end

function HouseInfoMgr:CreatGroupMemberRoomPopup()
    local function RCallback()
        local ArmyID = _G.ArmyMgr:GetArmyID()
        if ArmyID == 0 then
            _G.MsgTipsUtil.ShowTips(HouseLocalDef.HasExitedArmyTips)
        else
            self:SendCreateMemberRoom(ArmyID)
        end

        UIViewMgr:HideView(UIViewID.HelpInfoMidWinView)
    end

    local function LCallback()
        UIViewMgr:HideView(UIViewID.HelpInfoMidWinView)
    end
    
    local UIDefine = require("Define/UIDefine")
    local CommBtnColorType = UIDefine.CommBtnColorType
    local HelpInfoUtil = require("Utils/HelpInfoUtil")
    local HouseGlobalCfg = require("TableCfg/HouseGlobalCfg")
    local ScoreID = HouseGlobalCfg:GetValueByTypeID(ProtoRes.HouseGlobalCfgID.HouseGlobalCfgIDGroupMemberRoomMoneyType)
    local ScoreName = _G.ScoreMgr:GetScoreNameText(ScoreID)
    local ScoreCostNum = HouseGlobalCfg:GetValueByTypeID(ProtoRes.HouseGlobalCfgID.HouseGlobalCfgIDGroupMemberRoomMoneyNum)
    local ScoreValue = _G.ScoreMgr:GetScoreValueByID(ScoreID)
    local ExtraParam = {
        CostNum = _G.ScoreMgr.FormatScore(ScoreCostNum),
        CostItemID = ScoreID,
        CommTipsBtn1Str = HouseLocalDef.LocalTxtStr.BtnCancel,
        CommTipsBtn2Str = HouseLocalDef.LocalTxtStr.BtnSure,
        Btn2Callback = RCallback,
        Btn1Callback = LCallback,
        ShowBtn = true,
        CostColor = ScoreValue >= ScoreCostNum and "FFFFFFFF" or "FF0000FF",
        RightBtnOpState = CommBtnColorType.Recommend,
        LeftBtnOpState = CommBtnColorType.Normal
    } 

    HelpInfoUtil.ShowHelpInfoByID(11235 ,ExtraParam, nil, _G.ScoreMgr.FormatScore(ScoreCostNum), ScoreName)
end

--- 炫酷闪光入场动画你播了没
function HouseInfoMgr:IsAnimationUltraPlay(NameStr, IsEveryDay)
    local CurTime = TimeUtil.GetServerLogicTime()
    local JsonStr = USaveMgr.GetString(SaveKey.HouseSystem, "", true)
    local HouseSaveData = string.isnilorempty(JsonStr) and {} or Json.decode(JsonStr)
    local IsPlayed
    if not HouseSaveData[NameStr] then
        IsPlayed = false
    else
        if IsEveryDay then
            IsPlayed = TimeUtil:IsSameDay(tonumber(HouseSaveData[NameStr]), CurTime)
        else
            IsPlayed = true
        end
    end

    HouseSaveData[NameStr] = CurTime
    local SaveJsonStr = Json.encode(HouseSaveData)
    USaveMgr.SetString(SaveKey.HouseSystem, SaveJsonStr, true)
    return IsPlayed
end

function HouseInfoMgr:ClearSaveCache()
    USaveMgr.SetString(SaveKey.HouseSystem, "", true)
end

return HouseInfoMgr